head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDMGT50322";

// [A] 초기 목록 미해결 — uldmgt50322: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50322.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_helpFaqs_2_oncellclick
 * @description grd_helpFaqs_2 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_helpFaqs_2_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_helpFaqs');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_helpFaqs */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.content(r["faqId"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_helpFaqs_2.oncellclick' });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name content
 * @description content 처리
 * @param {String} faqId faqId
 * @returns {void}
 * @hidden N
 */
scwin.content = function (faqId) {
    const cobj = document.all["faq_" + faqId];
    if (cobj.style.display === "none") {
        cobj.style.display = "block";
    } else {
        cobj.style.display = "none";
    }
};

/**
 * @method
 * @name addFaq
 * @description add Faq 처리
 * @returns {void}
 * @hidden N
 */
scwin.addFaq = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/ui/jsp/ULDMGT50321.xml') + dma_pageContext.get("helpClssId") + "&mode=create";
};

/**
 * @method
 * @name modFaq
 * @description mod Faq 처리
 * @param {String} faqId faqId
 * @returns {void}
 * @hidden N
 */
scwin.modFaq = function (faqId) {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/ui/jsp/ULDMGT50321.xml') + faqId + "&mode=update";
};

/**
 * @method
 * @name delFaq
 * @description del Faq 처리
 * @param {String} faqId faqId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delFaq = async function (faqId) {
    const _confirm = await $c.win.confirm("FAQ[" + faqId + "]를\n삭제하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.win.setPageFrameSrc($c.win.getFrame(), '/ui/jsp/ULDMGT50321.xml') + dma_pageContext.get("helpClssId") + "&faqId=" + faqId;
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};
